void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;


    vec2 dPdx = vec2(0.01,0);  // x方向的梯度
    vec2 dPdy = vec2(0,0.01);  // y方向的梯度

    // 使用 textureGrad 进行纹理采样，传入梯度来调整采样
    vec4 color = textureGrad(iChannel0, uv, dPdx, dPdy);

    // 输出最终的颜色
    fragColor = color;

}
